package com.industrial.defect.controller;
import com.industrial.defect.dto.keyboard.KeyboardInspectionResponse; import com.industrial.defect.service.KeyboardAnalysisClient; import com.industrial.defect.service.KeyboardInspectionService; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.UUID;
@RestController @RequestMapping("/api/keyboard-inspections") public class KeyboardInspectionController { private final KeyboardInspectionService service; private final KeyboardAnalysisClient client; public KeyboardInspectionController(KeyboardInspectionService s,KeyboardAnalysisClient c){service=s;client=c;} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<KeyboardInspectionResponse> create(@RequestParam("image") MultipartFile image,@RequestParam(value="deviceInfo",required=false) String deviceInfo){return ResponseEntity.ok(service.inspect(image,deviceInfo));} @GetMapping("/{inspectionId}") public KeyboardInspectionResponse get(@PathVariable UUID inspectionId){return service.get(inspectionId);} @GetMapping public Page<KeyboardInspectionResponse> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) String status,@RequestParam(required=false) Boolean hasDefect){return service.history(page,size,status,hasDefect);} @GetMapping("/{inspectionId}/assets/{filename:.+}") public ResponseEntity<byte[]> asset(@PathVariable UUID inspectionId,@PathVariable String filename){if(!filename.matches("[a-z_]+\\.png"))throw new IllegalArgumentException("Tên asset không hợp lệ.");return ResponseEntity.ok().contentType(MediaType.IMAGE_PNG).body(client.asset(inspectionId.toString(),filename));} }
